@inject IAppointmentService AppointmentService

<PageTitle>Book Appointment</PageTitle>

<h3>Book a Medical Appointment</h3>

<EditForm Model="@form" OnValidSubmit="HandleSubmit">
    <DataAnnotationsValidator />

    <h4>Step 1: Patient Information</h4>

    <div class="mb-3">
        <label class="form-label" for="patientName">Patient Name</label>
        <InputText id="patientName" class="form-control" @bind-Value="form.PatientName" />
        <ValidationMessage For="@(() => form.PatientName)" />
    </div>

    <div class="mb-3">
        <label class="form-label" for="email">Email</label>
        <InputText id="email" class="form-control" @bind-Value="form.Email" />
        <ValidationMessage For="@(() => form.Email)" />
        @if (serverErrors.ContainsKey(nameof(form.Email)))
        {
            <div class="validation-message">@serverErrors[nameof(form.Email)]</div>
        }
    </div>

    <div class="mb-3">
        <label class="form-label" for="phone">Phone</label>
        <InputText id="phone" class="form-control" @bind-Value="form.Phone" />
        <ValidationMessage For="@(() => form.Phone)" />
    </div>

    <div class="mb-3">
        <label class="form-label" for="insurance">Insurance Provider</label>
        <InputSelect id="insurance" class="form-select" @bind-Value="form.InsuranceProvider">
            <option value="">-- Select --</option>
            <option value="Aetna">Aetna</option>
            <option value="BlueCross">BlueCross</option>
            <option value="Cigna">Cigna</option>
            <option value="UnitedHealth">UnitedHealth</option>
            <option value="None">None</option>
        </InputSelect>
        <ValidationMessage For="@(() => form.InsuranceProvider)" />
    </div>

    @if (!showStep2)
    {
        <button type="button" class="btn btn-primary" @onclick="ProceedToStep2">Next</button>
    }

    @if (showStep2)
    {
        <hr />
        <h4>Step 2: Appointment Details</h4>

        <div class="mb-3">
            <label class="form-label" for="doctor">Preferred Doctor</label>
            <InputSelect id="doctor" class="form-select" @bind-Value="form.Doctor"
                         @bind-Value:after="OnDoctorOrDateChanged">
                <option value="">-- Select --</option>
                @foreach (var doc in doctors)
                {
                    <option value="@doc">@doc</option>
                }
            </InputSelect>
            <ValidationMessage For="@(() => form.Doctor)" />
            @if (serverErrors.ContainsKey(nameof(form.Doctor)))
            {
                <div class="validation-message">@serverErrors[nameof(form.Doctor)]</div>
            }
        </div>

        <div class="mb-3">
            <label class="form-label" for="date">Date</label>
            <InputDate id="date" class="form-control" @bind-Value="form.AppointmentDate"
                       @bind-Value:after="OnDoctorOrDateChanged" />
            <ValidationMessage For="@(() => form.AppointmentDate)" />
            @if (dateError is not null)
            {
                <div class="validation-message">@dateError</div>
            }
        </div>

        <div class="mb-3">
            <label class="form-label" for="timeSlot">Time Slot</label>
            <InputSelect id="timeSlot" class="form-select" @bind-Value="form.TimeSlot">
                <option value="">-- Select --</option>
                @foreach (var slot in timeSlots)
                {
                    <option value="@slot">@slot</option>
                }
            </InputSelect>
            <ValidationMessage For="@(() => form.TimeSlot)" />
            @if (serverErrors.ContainsKey(nameof(form.TimeSlot)))
            {
                <div class="validation-message">@serverErrors[nameof(form.TimeSlot)]</div>
            }
        </div>

        <div class="mb-3">
            <label class="form-label" for="reason">Reason for Visit</label>
            <InputTextArea id="reason" class="form-control" rows="3" @bind-Value="form.ReasonForVisit" />
            <ValidationMessage For="@(() => form.ReasonForVisit)" />
        </div>

        <button type="button" class="btn btn-secondary me-2" @onclick="CheckAvailability"
                disabled="@isSubmitting">
            @(isSubmitting ? "Checking..." : "Check Availability")
        </button>
        <button type="submit" class="btn btn-success" disabled="@(!availabilityConfirmed || isSubmitting)">
            Book Appointment
        </button>
    }
</EditForm>

@if (booked)
{
    <div class="alert alert-success mt-3">
        Appointment booked successfully!
    </div>
}

