@page "/book-appointment"
@rendermode InteractiveServer
@using sv_5dcafba4d046443b9d298f82e4e943d7.Models
@using sv_5dcafba4d046443b9d298f82e4e943d7.Services
@inject IAppointmentService AppointmentService

<PageTitle>Book Appointment</PageTitle>

<h3>Book a Medical Appointment</h3>

<EditForm Model="@form" OnValidSubmit="HandleSubmit">
    <DataAnnotationsValidator />

    <h4>Step 1: Patient Information</h4>

    <div class="mb-3">
        <label class="form-label" for="patientName">Patient Name</label>
        <InputText id="patientName" class="form-control" @bind-Value="form.PatientName" />
        <ValidationMessage For="@(() => form.PatientName)" />
    </div>

    <div class="mb-3">
        <label class="form-label" for="email">Email</label>
        <InputText id="email" class="form-control" @bind-Value="form.Email" />
        <ValidationMessage For="@(() => form.Email)" />
        @if (serverErrors.ContainsKey(nameof(form.Email)))
        {
            <div class="validation-message">@serverErrors[nameof(form.Email)]</div>
        }
    </div>

    <div class="mb-3">
        <label class="form-label" for="phone">Phone</label>
        <InputText id="phone" class="form-control" @bind-Value="form.Phone" />
        <ValidationMessage For="@(() => form.Phone)" />
    </div>

    <div class="mb-3">
        <label class="form-label" for="insurance">Insurance Provider</label>
        <InputSelect id="insurance" class="form-select" @bind-Value="form.InsuranceProvider">
            <option value="">-- Select --</option>
            <option value="Aetna">Aetna</option>
            <option value="BlueCross">BlueCross</option>
            <option value="Cigna">Cigna</option>
            <option value="UnitedHealth">UnitedHealth</option>
            <option value="None">None</option>
        </InputSelect>
        <ValidationMessage For="@(() => form.InsuranceProvider)" />
    </div>

    @if (!showStep2)
    {
        <button type="button" class="btn btn-primary" @onclick="ProceedToStep2">Next</button>
    }

    @if (showStep2)
    {
        <hr />
        <h4>Step 2: Appointment Details</h4>

        <div class="mb-3">
            <label class="form-label" for="doctor">Preferred Doctor</label>
            <InputSelect id="doctor" class="form-select" @bind-Value="form.Doctor"
                         @bind-Value:after="OnDoctorOrDateChanged">
                <option value="">-- Select --</option>
                @foreach (var doc in doctors)
                {
                    <option value="@doc">@doc</option>
                }
            </InputSelect>
            <ValidationMessage For="@(() => form.Doctor)" />
            @if (serverErrors.ContainsKey(nameof(form.Doctor)))
            {
                <div class="validation-message">@serverErrors[nameof(form.Doctor)]</div>
            }
        </div>

        <div class="mb-3">
            <label class="form-label" for="date">Date</label>
            <InputDate id="date" class="form-control" @bind-Value="form.AppointmentDate"
                       @bind-Value:after="OnDoctorOrDateChanged" />
            <ValidationMessage For="@(() => form.AppointmentDate)" />
            @if (dateError is not null)
            {
                <div class="validation-message">@dateError</div>
            }
        </div>

        <div class="mb-3">
            <label class="form-label" for="timeSlot">Time Slot</label>
            <InputSelect id="timeSlot" class="form-select" @bind-Value="form.TimeSlot">
                <option value="">-- Select --</option>
                @foreach (var slot in timeSlots)
                {
                    <option value="@slot">@slot</option>
                }
            </InputSelect>
            <ValidationMessage For="@(() => form.TimeSlot)" />
            @if (serverErrors.ContainsKey(nameof(form.TimeSlot)))
            {
                <div class="validation-message">@serverErrors[nameof(form.TimeSlot)]</div>
            }
        </div>

        <div class="mb-3">
            <label class="form-label" for="reason">Reason for Visit</label>
            <InputTextArea id="reason" class="form-control" rows="3" @bind-Value="form.ReasonForVisit" />
            <ValidationMessage For="@(() => form.ReasonForVisit)" />
        </div>

        <button type="button" class="btn btn-secondary me-2" @onclick="CheckAvailability"
                disabled="@isSubmitting">
            @(isSubmitting ? "Checking..." : "Check Availability")
        </button>
        <button type="submit" class="btn btn-success" disabled="@(!availabilityConfirmed || isSubmitting)">
            Book Appointment
        </button>
    }
</EditForm>

@if (booked)
{
    <div class="alert alert-success mt-3">
        Appointment booked successfully!
    </div>
}

@code {
    private AppointmentForm form = new();
    private List<string> doctors = new();
    private List<string> timeSlots = new();
    private Dictionary<string, string> serverErrors = new();
    private string? dateError;
    private bool showStep2;
    private bool availabilityConfirmed;
    private bool isSubmitting;
    private bool booked;

    private EditContext? editContext;

    protected override async Task OnInitializedAsync()
    {
        editContext = new EditContext(form);
        doctors = await AppointmentService.GetDoctorsAsync();
    }

    private void ProceedToStep2()
    {
        editContext = new EditContext(form);
        var step1Properties = new[]
        {
            editContext.Field(nameof(form.PatientName)),
            editContext.Field(nameof(form.Email)),
            editContext.Field(nameof(form.Phone)),
            editContext.Field(nameof(form.InsuranceProvider))
        };

        // Trigger validation for step 1 fields only
        var validator = new DataAnnotationsValidator();
        editContext.Validate();

        var messages = editContext.GetValidationMessages();
        var step1Fields = new HashSet<string>
        {
            nameof(form.PatientName),
            nameof(form.Email),
            nameof(form.Phone),
            nameof(form.InsuranceProvider)
        };

        var step1Messages = editContext.GetValidationMessages()
            .Where((_, i) =>
            {
                // Check if the message belongs to step 1 fields
                return true;
            });

        // Validate step 1 fields manually
        bool isStep1Valid = true;
        if (string.IsNullOrWhiteSpace(form.PatientName)) isStep1Valid = false;
        if (string.IsNullOrWhiteSpace(form.Email) || !new System.ComponentModel.DataAnnotations.EmailAddressAttribute().IsValid(form.Email)) isStep1Valid = false;
        if (string.IsNullOrWhiteSpace(form.Phone)) isStep1Valid = false;
        if (string.IsNullOrWhiteSpace(form.InsuranceProvider)) isStep1Valid = false;

        if (isStep1Valid)
        {
            showStep2 = true;
        }
    }

    private async Task OnDoctorOrDateChanged()
    {
        availabilityConfirmed = false;
        serverErrors.Clear();

        if (!string.IsNullOrEmpty(form.Doctor) && form.AppointmentDate.HasValue)
        {
            timeSlots = await AppointmentService.GetAvailableTimeSlotsAsync(
                form.Doctor, form.AppointmentDate.Value);
            form.TimeSlot = string.Empty;
        }
    }

    private async Task CheckAvailability()
    {
        serverErrors.Clear();
        dateError = null;
        availabilityConfirmed = false;

        // Client-side date validation
        if (form.AppointmentDate.HasValue && form.AppointmentDate.Value <= DateOnly.FromDateTime(DateTime.Today))
        {
            dateError = "Date must be in the future.";
            return;
        }

        // Validate step 2 fields
        editContext = new EditContext(form);
        editContext.Validate();

        bool step2Valid = true;
        if (string.IsNullOrEmpty(form.Doctor)) step2Valid = false;
        if (!form.AppointmentDate.HasValue) step2Valid = false;
        if (string.IsNullOrEmpty(form.TimeSlot)) step2Valid = false;
        if (string.IsNullOrWhiteSpace(form.ReasonForVisit)) step2Valid = false;
        if (form.ReasonForVisit.Length > 500) step2Valid = false;

        if (!step2Valid) return;

        isSubmitting = true;
        try
        {
            var result = await AppointmentService.ValidatePatientAsync(form);

            if (!result.IsValid)
            {
                serverErrors = new Dictionary<string, string>(result.Errors);
            }
            else
            {
                availabilityConfirmed = true;
            }
        }
        finally
        {
            isSubmitting = false;
        }
    }

    private void HandleSubmit()
    {
        if (!availabilityConfirmed) return;
        booked = true;
    }
}

