            <ValidationMessage For="@(() => form.ReasonForVisit)" />
        </div>

        <button type="button" class="btn btn-secondary me-2" @onclick="CheckAvailability"
                disabled="@isSubmitting">
            @(isSubmitting ? "Checking..." : "Check Availability")
        </button>
        <button type="submit" class="btn btn-success" disabled="@(!availabilityConfirmed || isSubmitting)">
            Book Appointment
        </button>
    }
</EditForm>

@if (booked)
{
    <div class="alert alert-success mt-3">
        Appointment booked successfully!
    </div>
}

@code {
    private AppointmentForm form = new();
    private EditContext editContext = default!;
    private ValidationMessageStore messageStore = default!;
    private List<string> doctors = new();
    private List<string> timeSlots = new();
    private bool showStep2;
    private bool availabilityConfirmed;
    private bool isSubmitting;
    private bool booked;

    protected override async Task OnInitializedAsync()
    {
        editContext = new EditContext(form);
        messageStore = new ValidationMessageStore(editContext);
        editContext.OnFieldChanged += (_, args) =>
        {
            // Clear server errors for the changed field so the user can retry
            messageStore.Clear(args.FieldIdentifier);
            availabilityConfirmed = false;
        };
        doctors = await AppointmentService.GetDoctorsAsync();
    }

    private void ProceedToStep2()
    {
        messageStore.Clear();

        var step1Fields = new[]
        {
            nameof(AppointmentForm.PatientName),
            nameof(AppointmentForm.Email),
            nameof(AppointmentForm.Phone),
            nameof(AppointmentForm.InsuranceProvider)
        };

        var results = new List<System.ComponentModel.DataAnnotations.ValidationResult>();
        var ctx = new System.ComponentModel.DataAnnotations.ValidationContext(form);

        // Validate only step 1 properties
        bool isValid = true;
        foreach (var prop in step1Fields)
        {
            var pi = typeof(AppointmentForm).GetProperty(prop)!;
            var value = pi.GetValue(form);
            var fieldResults = new List<System.ComponentModel.DataAnnotations.ValidationResult>();
            var fieldCtx = new System.ComponentModel.DataAnnotations.ValidationContext(form) { MemberName = prop };

            if (!System.ComponentModel.DataAnnotations.Validator.TryValidateProperty(value, fieldCtx, fieldResults))
            {
                isValid = false;
                var fieldIdentifier = editContext.Field(prop);
                foreach (var r in fieldResults)
                {
                    messageStore.Add(fieldIdentifier, r.ErrorMessage!);
                }
            }
        }

        editContext.NotifyValidationStateChanged();

        if (isValid)
        {
            showStep2 = true;
        }
    }

    private async Task OnDoctorOrDateChanged()
    {
        availabilityConfirmed = false;

        if (!string.IsNullOrEmpty(form.Doctor) && form.AppointmentDate.HasValue)
        {
            timeSlots = await AppointmentService.GetAvailableTimeSlotsAsync(
                form.Doctor, form.AppointmentDate.Value);
            form.TimeSlot = string.Empty;
        }
    }

    private async Task CheckAvailability()
    {
        messageStore.Clear();
        availabilityConfirmed = false;

        // Validate all fields via DataAnnotations
        bool allValid = editContext.Validate();

        // Custom future-date check
        if (form.AppointmentDate.HasValue && form.AppointmentDate.Value <= DateOnly.FromDateTime(DateTime.Today))
        {
            messageStore.Add(editContext.Field(nameof(AppointmentForm.AppointmentDate)), "Date must be in the future.");
            editContext.NotifyValidationStateChanged();
            allValid = false;
        }

        if (!allValid) return;

        isSubmitting = true;
        try
        {
            var result = await AppointmentService.ValidatePatientAsync(form);

            if (!result.IsValid)
            {
                foreach (var (field, message) in result.Errors)
                {
                    messageStore.Add(editContext.Field(field), message);
                }
                editContext.NotifyValidationStateChanged();
            }
            else
            {
                availabilityConfirmed = true;
            }
        }
        finally
        {
            isSubmitting = false;
        }
    }

    private void HandleSubmit()
    {
        if (!availabilityConfirmed) return;
        booked = true;
    }
}"}

